local _, WFJ = ...
WFJ.Data.add("quest", {
  [65597] = { "Il vincolo", "Usando i Lovers' Hearts, evoca e sottometti un incubo, poi riporta i Lovers' Hearts a Carendin Halgar nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", "Il momento è finalmente giunto. Porta i cuori al cerchio di evocazione qui sotto. Mettili al centro e richiama l'incubo.\n\nIl demone non sarà contento quando si accorgerà che l'hai attirato in una trappola. Non cadere vittima delle sue lusinghe, {name}. Devi sottometterlo completamente.\n\nSolo allora potrò insegnarti l'incantesimo per vincolarlo alla tua volontà.", nil, nil, 0x5926988f, 0xf62852d5, 0x71f56f10, nil, nil, "...mm" },
  [65603] = { "Il vincolo", "Usando la Wooden Figurine, evoca e sottometti un incubo, poi riporta la Wooden Figurine a Gakin the Darkbinder allo Slaughtered Lamb.", "Il momento è giunto. Prendi la statuetta e scendi nelle cripte qui sotto. È stato preparato un cerchio di evocazione, e dovrai mettere la statuetta al suo centro.\n\nAllora il portale si aprirà e l'incubo varcherà la soglia del nostro mondo.\n\nUn sayaad non va sottovalutato. Il demone non esiterà ad attaccare quando scoprirà il tuo inganno. Dovrai attingere a tutto ciò che ti è stato insegnato per sconfiggerlo.\n\nSe ci riesci, torna da me e vincolerò la creatura alla tua volontà. Se fallisci, la tua anima è perduta.", nil, nil, 0x5926988f, 0x9a339fad, 0xfe44a9e9, nil, nil, "...mm" },
  [65604] = { "Il vincolo", "Usando la Withered Scarf, evoca e sottometti un incubo, poi riporta la Withered Scarf a Gan'rul Bloodeye a Orgrimmar.", "Sì... capisco. Sento le emozioni residue racchiuse in questi fili. L'amore è intessuto nelle sue cuciture. L'incubo non saprà resistere.\n\nPorta questo al cerchio di evocazione nella tenda di Neeru, {name}. Evoca un incubo malevolo, poi mostragli la tua padronanza. Non aspettarti che si lasci sottomettere docilmente. Prepara la tua magia e preparati a combattere. Sottovalutare un demone è stato l'ultimo errore di molti stregoni.\n\nQuando l'avrai sconfitto, riportami la stoffa. Farò sapere a Magar cosa hai trovato.", nil, nil, 0x5926988f, 0x4de62da3, 0xae8e63dd, nil, nil, "...mm" },
})
